insert into public.stores (id, config, device_key) values ('demo', $json${"storeName": {"zh": "红颜茶楼", "en": "Hong Yan Tea House"}, "languages": ["zh", "en"], "lines": {"zh": {"slogan": "走近一点，和我猜个拳吧！", "welcome": ["欢迎光临红颜茶楼！", "客官里边请～", "好久不见，今天想喝点什么？"], "invite": "举起手，跟我猜拳赢小礼品！", "win": "哇，你赢了！", "lose": "哈哈，我赢啦！送你一个安慰奖～", "draw": "平手！再来一次！", "noHand": "没看到你的手哦，再来一次～", "bye": "欢迎下次再来！"}, "en": {"slogan": "Come closer and play Rock Paper Scissors with me!", "welcome": ["Welcome to Hong Yan Tea House!", "Hello there, come on in!", "Hi! Thirsty today?"], "invite": "Raise your hand, beat me and win a gift!", "win": "Wow, you win!", "lose": "Haha, I win! Here's a little something anyway.", "draw": "It's a draw! One more time!", "noHand": "I can't see your hand, let's try again!", "bye": "See you next time!"}}, "prizes": [{"id": "p1", "name": {"zh": "免费柠檬茶一杯", "en": "Free Lemon Tea"}, "weight": 1, "stock": 10, "emoji": "🍋"}, {"id": "p2", "name": {"zh": "小吃券 RM5", "en": "RM5 Snack Voucher"}, "weight": 3, "stock": 30, "emoji": "🥟"}, {"id": "p3", "name": {"zh": "店铺贴纸", "en": "Shop Sticker"}, "weight": 6, "stock": null, "emoji": "🌸"}], "consolation": {"name": {"zh": "9折优惠券", "en": "10% Off Coupon"}, "emoji": "🎟️"}, "theme": {"primary": "#4a160f", "accent": "#f5d68a", "bg": "#6b2d1e"}, "character": {"skin": {"outfit": "#e74c3c", "outfitDark": "#c0392b", "hair": "#2c2c2c", "skin": "#ffe0bd"}, "media": {"idle": "", "wave": "", "happy": "", "sad": ""}}}$json$, 'test-key-demo');
insert into public.stores (id, config, device_key) values ('kopitiam-en', $json${"storeName": {"en": "Sunny Kopitiam"}, "languages": ["en"], "lines": {"en": {"slogan": "Come say hi! Play Rock Paper Scissors for a treat!", "welcome": ["Selamat datang to Sunny Kopitiam!", "Hello boss, come in lah!", "Hi! Kopi or teh today?"], "invite": "Raise your hand, beat me and win a gift!", "win": "Wah, you win!", "lose": "Haha, I win! Never mind, here's a small gift.", "draw": "Same same! One more time!", "noHand": "Cannot see your hand leh, try again!", "bye": "Thank you, come again!"}}, "prizes": [{"id": "p1", "name": {"en": "Free Kopi O"}, "weight": 2, "stock": 20, "emoji": "☕"}, {"id": "p2", "name": {"en": "Free Kaya Toast"}, "weight": 1, "stock": 10, "emoji": "🍞"}, {"id": "p3", "name": {"en": "RM2 Off Next Visit"}, "weight": 5, "stock": null, "emoji": "🎁"}], "consolation": {"name": {"en": "5% Off Coupon"}, "emoji": "🎟️"}, "theme": {"primary": "#0f3d2e", "accent": "#ffd23f", "bg": "#1f6b4f"}, "character": {"skin": {"outfit": "#2e9e6b", "outfitDark": "#1f6b4f", "hair": "#3b2a1a", "skin": "#e8b98a"}, "media": {"idle": "", "wave": "", "happy": "", "sad": ""}}}$json$, 'test-key-kopitiam-en');
